package org.telegram.messenger;

import org.json.*;
import org.telegram.messenger.devgram.player.TrackQuery;
import java.io.File;
import java.util.*;
import java.util.concurrent.*;

/** Account-bound queued tasks survive sheet dismissal; the API owns leases, results and notices. */
public final class DevGramLyricsJobs {
 public interface Callback{void done(JSONObject result,String error);}
 private static final ExecutorService AUDIO=Executors.newSingleThreadExecutor(r->{Thread t=new Thread(r,"devgram-lyric-audio");t.setDaemon(true);return t;});
 private static final ArrayDeque<Job> waiting=new ArrayDeque<>();private static final HashSet<String> queued=new HashSet<>();private static final java.util.concurrent.CopyOnWriteArraySet<Runnable> listeners=new java.util.concurrent.CopyOnWriteArraySet<>();
 private static Job active;private static DevGramAiClient.ToolRequest request;private static boolean bound;private static long lastResume;private static long lastResumeUid;private static int lastResumeAccount=-1;
 private static final Runnable retry=()->{if(lastResumeAccount==UserConfig.selectedAccount)resume(lastResumeAccount);};
 private static final class Job{final int account;final long uid,id;final JSONObject data;final File audio;String lease;volatile boolean stopped;Job(int account,JSONObject data,File audio){this.account=account;uid=UserConfig.getInstance(account).getClientUserId();this.data=data;id=data.optLong("id");this.audio=audio;}String key(){return account+":"+uid+":"+id;}}
 private static JSONObject json(Object... pairs){JSONObject value=new JSONObject();try{for(int i=0;i<pairs.length;i+=2)value.put(String.valueOf(pairs[i]),pairs[i+1]);}catch(Exception ignored){}return value;}
 private static boolean allowed(Job job){return job!=null&&!job.stopped&&UserConfig.selectedAccount==job.account&&UserConfig.getInstance(job.account).getClientUserId()==job.uid&&DevGramProfileCustomization.enabled()&&DevGramProfilePolicy.allowed(job.uid,"music.lyrics")&&DevGramProfilePolicy.allowed(job.uid,"profile.assistant");}
 private static final Runnable policy=()->{if(active!=null&&!allowed(active)){active.stopped=true;if(request!=null)request.cancel();request=null;complete(active);}};
 public static void listen(Runnable listener){listeners.add(listener);}public static void unlisten(Runnable listener){listeners.remove(listener);}private static void changed(){for(Runnable listener:listeners)listener.run();}
 public static void variants(TrackQuery query,Callback callback){DevGramProfilePolicy.executeWorkshop(()->{JSONObject response=null;try{response=DevGramProfilePolicy.http("GET","studio/lyrics?title="+java.net.URLEncoder.encode(query.title(),"UTF-8")+"&artist="+java.net.URLEncoder.encode(query.artist()==null?"":query.artist(),"UTF-8")+"&duration="+query.duration(),null);}catch(Exception ignored){}JSONObject answer=response;AndroidUtilities.runOnUIThread(()->callback.done(answer,answer==null?"lyrics_unavailable":null));});}
 public static void list(int account,Callback callback){DevGramProfilePolicy.request(account,"studio/lyrics/jobs",json("action","list"),(data,error)->callback.done(data,error));}
 public static void cancel(int account,long id,Callback callback){if(active!=null&&active.account==account&&active.id==id){active.stopped=true;if(request!=null)request.cancel();complete(active);}for(Iterator<Job> iterator=waiting.iterator();iterator.hasNext();){Job job=iterator.next();if(job.account==account&&job.id==id){job.stopped=true;queued.remove(job.key());iterator.remove();}}DevGramProfilePolicy.request(account,"studio/lyrics/jobs",json("action","cancel","id",id),(data,error)->{changed();callback.done(data,error);});}
 public static void submit(int account,TrackQuery query,String kind,String language,String lyrics,File audio,Callback callback){
  long uid=UserConfig.getInstance(account).getClientUserId();JSONObject body=json("action","submit","title",query.title(),"artist",query.artist()==null?"":query.artist(),"duration",Math.max(0,query.duration()),"kind",kind,"language",language==null?"":language,"lyrics",lyrics==null?"":lyrics);
  DevGramProfilePolicy.request(account,"studio/lyrics/jobs",body,(data,error)->{if(UserConfig.getInstance(account).getClientUserId()!=uid)return;JSONObject value=data==null?null:data.optJSONObject("job");if(value!=null){if(audio!=null)MessagesController.getGlobalMainSettings().edit().putString("devgramLyricsAudio_"+account+"_"+uid+"_"+value.optLong("id"),audio.getPath()).apply();enqueue(new Job(account,value,audio));changed();}callback.done(data,error);});
 }
 public static void resume(int account){if(UserConfig.selectedAccount!=account)return;long currentUid=UserConfig.getInstance(account).getClientUserId();if(account!=lastResumeAccount||currentUid!=lastResumeUid){lastResume=0;lastResumeAccount=account;lastResumeUid=currentUid;}long now=android.os.SystemClock.elapsedRealtime();if(now-lastResume<20000||!DevGramAiClient.isConfigured()||!DevGramProfileCustomization.enabled())return;lastResume=now;long uid=UserConfig.getInstance(account).getClientUserId();if(!DevGramProfilePolicy.allowed(uid,"music.lyrics")||!DevGramProfilePolicy.allowed(uid,"profile.assistant"))return;list(account,(data,error)->{if(data==null||UserConfig.getInstance(account).getClientUserId()!=uid)return;boolean[] pending={false};JSONArray jobs=data.optJSONArray("jobs");for(int i=0;jobs!=null&&i<jobs.length();i++){JSONObject job=jobs.optJSONObject(i);if(job!=null&&(job.optString("state").equals("queued")||job.optString("state").equals("running"))){String path=MessagesController.getGlobalMainSettings().getString("devgramLyricsAudio_"+account+"_"+uid+"_"+job.optLong("id"),"");File audio=path.isEmpty()?null:new File(path);if(job.optString("kind").equals("translate")||audio!=null&&audio.isFile()){pending[0]=true;enqueue(new Job(account,job,audio));}}}if(pending[0]){AndroidUtilities.cancelRunOnUIThread(retry);AndroidUtilities.runOnUIThread(retry,21000);}});}
 private static void enqueue(Job job){if(!allowed(job)||!queued.add(job.key()))return;if(!bound){bound=true;DevGramProfilePolicy.listen(policy);}waiting.addLast(job);next();}
 private static void next(){if(active!=null)return;while(!waiting.isEmpty()){Job job=waiting.removeFirst();if(!allowed(job)){queued.remove(job.key());continue;}active=job;claim(job);return;}}
 private static void claim(Job job){DevGramProfilePolicy.request(job.account,"studio/lyrics/jobs",json("action","claim","id",job.id),(result,error)->{if(active!=job||!allowed(job)){complete(job);return;}job.lease=result==null?"":result.optString("lease");if(job.lease.isEmpty()){complete(job);return;}String lyrics=result.optString("lyrics");String kind=job.data.optString("kind");String system="You process the exact supplied song. Return only lyrics as plain text or LRC, no markdown or commentary. Never invent missing words or timing. If the audio cannot be understood, return an empty string. Keep timestamps chronological. Translation preserves every original line and its exact LRC timestamp. Audio transcription and alignment require real audio; return a timestamp at the actual start of every sung line. Do not retrieve a remembered song instead of listening to the supplied audio.";String prompt="Track: "+job.data.optString("title")+" — "+job.data.optString("artist")+"\nDuration seconds: "+job.data.optInt("duration")+"\n"+(kind.equals("translate")?"Translate into "+job.data.optString("language")+". Preserve existing timestamps and line order.\n":kind.equals("timecodes")?"Align the supplied exact lyrics with the attached audio and return LRC.\n":"Transcribe the attached audio into timestamped LRC.\n")+lyrics;
   if(kind.equals("translate")){bindRequest(job,DevGramAiClient.generateTool(new JSONArray(),prompt,system,(answer,failure)->finished(job,answer,failure)));}else AUDIO.execute(()->{try{if(!allowed(job))throw new java.io.IOException("cancelled");DevGramLyricsAudio.Audio audio=DevGramLyricsAudio.read(job.audio,()->job.stopped);AndroidUtilities.runOnUIThread(()->{if(active!=job||!allowed(job)){complete(job);return;}bindRequest(job,DevGramAiClient.generateAudioTool(audio.bytes,audio.format,prompt,system,(answer,failure)->finished(job,answer,failure)));});}catch(Exception | OutOfMemoryError failure){AndroidUtilities.runOnUIThread(()->finished(job,null,failure));}});
  });}
 private static void bindRequest(Job job,DevGramAiClient.ToolRequest token){if(active==job&&allowed(job))request=token;else token.cancel();}
 private static void finished(Job job,String answer,Throwable failure){if(active!=job||!allowed(job)){complete(job);return;}String text=answer==null?"":answer.trim();if(text.startsWith("```")){int start=text.indexOf('\n'),end=text.lastIndexOf("```");if(start>=0&&end>start)text=text.substring(start+1,end).trim();}JSONObject body=json("action",failure==null&&!text.isEmpty()?"finish":"fail","id",job.id,"lease",job.lease);try{if(failure==null&&!text.isEmpty())body.put("lyrics",text);else{String message=failure==null?"":String.valueOf(failure.getMessage());body.put("code",message.contains("input_audio")||message.contains("audio_model_required")?"audio_model_required":message.contains("audio_unavailable")?"audio_unavailable":"generation_failed");}}catch(Exception ignored){}DevGramProfilePolicy.request(job.account,"studio/lyrics/jobs",body,(data,error)->{if(active!=job)return;if(data==null&&error!=null&&error.contains("bad_lyrics")&&body.optString("action").equals("finish")){DevGramProfilePolicy.request(job.account,"studio/lyrics/jobs",json("action","fail","id",job.id,"lease",job.lease,"code","invalid_lyrics"),(ignored,failureText)->{changed();complete(job);});return;}if(data!=null){MessagesController.getGlobalMainSettings().edit().remove("devgramLyricsAudio_"+job.account+"_"+job.uid+"_"+job.id).apply();if(job.audio!=null&&job.audio.getParentFile().equals(new File(ApplicationLoader.applicationContext.getCacheDir(),"devgram-lyrics-audio")))job.audio.delete();}DevGramCustomizationNotices.refresh(true);changed();complete(job);});}
 private static void complete(Job job){if(active!=job)return;queued.remove(job.key());active=null;request=null;next();if(active==null&&waiting.isEmpty()&&bound){bound=false;DevGramProfilePolicy.unlisten(policy);}}
}
